#pragma once
// Explicit engineering source budgets, not source-noise W. Opt-in only.
#include "rinkfit/joint_builder.hpp"
#include <cmath>
#include <set>
#include <cstring>
namespace rinkfit {
struct JointCaptureWeightsV3 {bool enabled=false;std::vector<double>per_row_weight;eventio::Json receipt=eventio::Json::object();};
namespace capture_weights_v3_detail {
inline std::filesystem::path checked(const eventio::Json&r){if(!r.is_object()||!r.contains("file")||!r.contains("sha256"))throw std::runtime_error("source weight reference lacks file/SHA");const auto p=std::filesystem::u8path(r.at("file").get<std::string>());if(!p.is_absolute()||r.at("sha256").get<std::string>().size()!=64)throw std::runtime_error("source weight reference is not exact absolute SHA binding");eventio::verify(p,r.at("sha256"));return p;}
template<class T>inline std::vector<T> binary(const eventio::Json&r,std::size_t n,const std::string&dtype){if(r.at("dtype")!=dtype||r.at("shape")!=eventio::Json::array({n}))throw std::runtime_error("source weight binary type/shape differs");const auto bytes=eventio::bytes(checked(r));if(bytes.size()!=n*sizeof(T))throw std::runtime_error("source weight binary size differs");std::vector<T>v(n);if(!bytes.empty())std::memcpy(v.data(),bytes.data(),bytes.size());return v;}
inline std::string keys(const JointPacket&p,std::size_t n){if(n>p.rows.size())throw std::runtime_error("source weight key prefix overflow");std::string text;for(std::size_t i=0;i<n;++i){const auto&r=p.rows[i];std::vector<std::string>f={std::to_string(i),r.source_dataset_id,r.source_row_id,r.shot_id,std::to_string(r.pts)};for(std::size_t k=0;k<f.size();++k){if(f[k].find_first_of("\x1f\r\n")!=std::string::npos)throw std::runtime_error("source key delimiter ambiguity");if(k)text.push_back('\x1f');text+=f[k];}text.push_back('\n');}return eventio::sha256(std::vector<std::uint8_t>(text.begin(),text.end()));}
inline bool bits(double a,double b){return std::memcmp(&a,&b,sizeof(double))==0;}
}
inline JointCaptureWeightsV3 load_joint_capture_weights_v3(const eventio::Json&cfg,const JointProblemBuilder&core){
 JointCaptureWeightsV3 result;if(!cfg.contains("engineering_source_weights_v3"))return result;using namespace capture_weights_v3_detail;
 const auto file=checked(cfg.at("engineering_source_weights_v3"));const auto j=eventio::read_json(file);if(j.at("schema")!="rinkfit.explicit_engineering_source_weights.v3")throw std::runtime_error("source weight schema differs");
 const auto source=checked(j.at("source_packet"));if(j.at("source_packet").at("sha256")!=core.packet.source_hash)throw std::runtime_error("source weights bound to another actual source packet");
 checked(j.at("parent_packet"));checked(j.at("parent_pixel_ledger"));checked(j.at("parent_complete_checkpoint"));checked(j.at("issuer"));checked(j.at("source_board_qualification"));const auto bp=checked(j.at("parent_complete_binding"));const auto parent=eventio::read_json(bp);if(parent.at("state_token")!=j.at("parent_state_token")||parent.at("packet_sha256")!=j.at("parent_packet").at("sha256"))throw std::runtime_error("source weight parent token/source differs");
 const auto n=core.packet.rows.size(),old=j.at("parent_rows").get<std::size_t>();if(j.at("raw_rows")!=n||old>n||j.at("source_key_registry_sha256")!=keys(core.packet,n)||j.at("parent_prefix_key_registry_sha256")!=keys(core.packet,old))throw std::runtime_error("source weights raw-index/source-id/clock registry differs");
 const auto ledger=eventio::read_json(j.at("parent_pixel_ledger").at("file").get<std::string>());if(ledger.at("schema")!="rinkfit.engineering_pixel_contributions.v1"||ledger.at("active_rows")!=j.at("parent_active_rows")||ledger.value("original_W_likelihood_consumed",true))throw std::runtime_error("source weight parent ledger semantics differ");
 const auto&files=j.at("files");auto weights=binary<double>(files.at("weights.f64"),n,"<f8");auto active=binary<std::uint8_t>(files.at("active.u8"),n,"|u1");auto info=binary<std::uint8_t>(files.at("information_class.u8"),n,"|u1");auto groups=binary<std::uint32_t>(files.at("parent_group.u32"),old,"<u4");std::vector<std::size_t>counts(ledger.at("groups").size());std::set<std::size_t>withdrawn;for(const auto&i:j.at("parent_withdrawn_to_pending_rows"))if(!withdrawn.insert(i.get<std::size_t>()).second)throw std::runtime_error("duplicated withdrawn source weight row");
 std::vector<double>E;E.reserve(n);std::size_t used=0,newcount=0,inherited=0;long double total=0,newbudget=0,parentbudget=0,retainedbudget=0;for(std::size_t i=0;i<n;++i){const auto&r=core.packet.rows[i];E.push_back(r.E);if(!std::isfinite(r.E)||r.E<=0||!std::isfinite(weights[i])||weights[i]<0||active[i]!=(r.active?1:0)||(weights[i]>0)!=r.active||info[i]>3)throw std::runtime_error("source weights active partition/positive finite E/weight failure at "+std::to_string(i));if(!r.active&&info[i]!=0)throw std::runtime_error("inactive source carries information class");if(r.active){++used;total+=weights[i];}
  if(i<old){if(groups[i]==0xffffffffu){if(r.active||weights[i]!=0)throw std::runtime_error("source weight revives inactive parent source");continue;}if(groups[i]>=counts.size())throw std::runtime_error("source weight parent group outside ledger");++counts[groups[i]];const auto&g=ledger.at("groups").at(groups[i]);const double expected=g.at("per_row_weight");if(!std::isfinite(expected)||expected<=0||g.at("shot")!=r.shot_id||g.at("native_pts")!=r.pts)throw std::runtime_error("source weight parent exposure/positive budget differs");const auto&label=core.model.materials.at(r.material).label;const std::string family=label.rfind("board.",0)==0?"board":label.rfind("Ad",0)==0||label.rfind("advertisement",0)==0?"advertisement":"ice";if(g.at("family")!=family)throw std::runtime_error("source weight parent physical information family differs");parentbudget+=expected;if(r.active){if(!bits(weights[i],expected)||info[i]!=(r.kind==1?1:2)||withdrawn.count(i))throw std::runtime_error("inherited source L2 budget or 2D information class drift");++inherited;retainedbudget+=weights[i];}else if(!withdrawn.count(i)||weights[i]!=0)throw std::runtime_error("parent source removed outside exact pending list");
  }else if(r.active){const auto&label=core.model.materials.at(r.material).label;if(info[i]!=3||r.kind==1||!r.query||r.query->alpha.size()!=49||r.shot_id!="s02"||(label!="board.top"&&label!="board.contact"))throw std::runtime_error("new source budget is not actual independent normal-profile channel");++newcount;newbudget+=weights[i];}
 }
 for(std::size_t k=0;k<counts.size();++k)if(counts[k]!=ledger.at("groups").at(k).at("rows").get<std::size_t>())throw std::runtime_error("parent ledger full source denominator differs");const auto*raw=reinterpret_cast<const std::uint8_t*>(E.data());if(j.at("source_E_binary64_le_sha256")!=eventio::sha256(std::vector<std::uint8_t>(raw,raw+E.size()*sizeof(double))))throw std::runtime_error("source original E bits differ");long double authority=0;for(const auto&g:ledger.at("groups"))if(g.at("shot")=="s02"&&g.at("family")=="board")authority+=(long double)g.at("rows").get<std::size_t>()*g.at("per_row_weight").get<double>();auto same=[](double a,double b){return std::isfinite(a)&&std::isfinite(b)&&std::abs(a-b)<=1e-9*std::max({1.,std::abs(a),std::abs(b)});};if(used!=j.at("active_rows")||newcount!=j.at("new_direct_normal_profile_rows")||inherited!=j.at("inherited_active_rows")||!same(double(newbudget),double(authority))||!same(double(total),j.at("actual_total_engineering_budget"))||!same(double(parentbudget),j.at("parent_original_total_budget"))||!same(double(retainedbudget),j.at("retained_parent_budget")))throw std::runtime_error("source engineering channel budget accounting differs");
 if(j.at("source_noise_W_or_sigma_issued")!=false||j.at("statistical_precision_or_noise_independence_claimed")!=false||j.at("source_source_UV_Query_W_or_E_changed")!=false)throw std::runtime_error("source weight policy may not issue noise precision or alter source");
 result.enabled=true;result.per_row_weight=std::move(weights);result.receipt={{"schema","rinkfit.actual_explicit_engineering_source_weight_consumption.v3"},{"binding",cfg.at("engineering_source_weights_v3")},{"parent_state_token",j.at("parent_state_token")},{"source_packet_sha256",core.packet.source_hash},{"active_rows",used},{"inherited_source_rows",inherited},{"new_direct_normal_profile_rows",newcount},{"retained_parent_budget",double(retainedbudget)},{"new_profile_channel_budget",double(newbudget)},{"actual_total_engineering_budget",double(total)},{"old_2D_point_or_keyframe_L2_budget_changed",false},{"original_E_UV_Query_and_W_changed",false},{"engineering_is_noise_likelihood",false},{"positive_finite_weights_and_complete_active_partition",true},{"raw_source_row_ID_clock_registry_verified",true}};return result;
}
}
